import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
test('start script', () => {
  const pkg = JSON.parse(readFileSync('package.json', 'utf8'))
  assert.match(pkg.scripts.start, /node\s+(\.\/)?src\/server\.js/)
  assert.equal(pkg.scripts.test, 'node --test')
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'
const app = createApp(Inventory.fromFile())
const ids = (r) => r.body.map((b) => b.id).sort()
test('filters', async () => {
  assert.deepEqual(ids(await app({ method: 'GET', url: '/books?author=MARTIN' })), ['b2', 'b3', 'b4'])
  assert.deepEqual(ids(await app({ method: 'GET', url: '/books?tag=design' })), ['b3', 'b8'])
  assert.deepEqual(ids(await app({ method: 'GET', url: '/books?tag=craft&author=fowler' })), ['b3'])
  assert.equal((await app({ method: 'GET', url: '/books' })).body.length, 8)
  assert.deepEqual((await app({ method: 'GET', url: '/books?tag=nope' })).body, [])
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'
const app = createApp(Inventory.fromFile())
const q = (body) => app({ method: 'POST', url: '/cart/quote', body })
test('validation', async () => {
  for (const body of [{}, { items: [] }, { items: [{ id: 'nope', quantity: 1 }] }, { items: [{ id: 'b1', quantity: 0 }] }, { items: [{ id: 'b1', quantity: 'two' }] }, { items: [{ id: 'b1', quantity: 1 }], discountCode: 'FREE' }]) {
    const r = await q(body)
    assert.equal(r.status, 400, JSON.stringify(body))
    assert.equal(typeof r.body.error, 'string')
  }
  const ok = await q({ items: [{ id: 'b6', quantity: 1 }] })
  assert.equal(ok.status, 200)
  assert.equal(ok.body.totalCents, 3239)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { Inventory } from '../src/inventory.js'
import { summary, render } from '../src/report.js'
const books = () => Inventory.fromFile().list()
test('low stock', () => {
  const s = summary(books(), { generatedAt: '2026-01-01' })
  assert.deepEqual(s.lowStock.map((b) => b.id), ['b8', 'b5', 'b2'])
  assert.deepEqual(s.lowStock[0], { id: 'b8', title: 'Domain-Driven Design', stock: 1 })
  const text = render(books(), 'text', { generatedAt: '2026-01-01' })
  assert.match(text, /low stock/i)
  assert.match(text, /Domain-Driven Design/)
  assert.match(text, /By author/)
  const md = render(books(), 'markdown', { generatedAt: '2026-01-01' })
  assert.match(md, /low stock/i)
  assert.match(md, /## By decade/)
  const none = summary(books().filter((b) => b.stock > 3 || b.stock === 0), { generatedAt: '2026-01-01' })
  assert.deepEqual(none.lowStock, [])
  assert.doesNotMatch(render(books().filter((b) => b.stock > 3), 'text', { generatedAt: '2026-01-01' }), /low stock/i)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'
const app = createApp(Inventory.fromFile())
const get = (url) => app({ method: 'GET', url })
const hdr = (r, k) => Object.fromEntries(Object.entries(r.headers ?? {}).map(([a, b]) => [a.toLowerCase(), String(b)]))[k]
test('pagination', async () => {
  const p1 = await get('/books?page=1&limit=3')
  assert.equal(p1.status, 200)
  assert.deepEqual(p1.body.map((b) => b.id), ['b1', 'b2', 'b3'])
  assert.equal(hdr(p1, 'x-total-count'), '8')
  const p3 = await get('/books?page=3&limit=3')
  assert.deepEqual(p3.body.map((b) => b.id), ['b7', 'b8'])
  assert.deepEqual((await get('/books?page=9&limit=3')).body, [])
  assert.equal((await get('/books?limit=500')).body.length, 8)
  for (const u of ['/books?page=0', '/books?limit=-1', '/books?page=abc']) assert.equal((await get(u)).status, 400, u)
  assert.equal((await get('/books')).body.length, 8)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp, startServer } from '../src/server.js'
import { Inventory } from '../src/inventory.js'
const app = createApp(Inventory.fromFile())
const hdr = (r, k) => Object.fromEntries(Object.entries(r.headers ?? {}).map(([a, b]) => [a.toLowerCase(), String(b)]))[k]
test('report endpoint (handler)', async () => {
  const t = await app({ method: 'GET', url: '/reports/inventory' })
  assert.equal(t.status, 200)
  assert.equal(typeof t.body, 'string')
  assert.match(t.body, /INVENTORY REPORT/)
  assert.match(hdr(t, 'content-type'), /text\/plain/)
  const csv = await app({ method: 'GET', url: '/reports/inventory?format=csv' })
  assert.match(hdr(csv, 'content-type'), /text\/csv/)
  assert.match(csv.body, /^id,title,author/)
  const md = await app({ method: 'GET', url: '/reports/inventory?format=markdown' })
  assert.match(hdr(md, 'content-type'), /text\/markdown/)
  assert.equal((await app({ method: 'GET', url: '/reports/inventory?format=pdf' })).status, 400)
})
test('report endpoint (http)', async () => {
  const server = startServer(0)
  await new Promise((r) => server.once('listening', r))
  const port = server.address().port
  try {
    const res = await fetch(`http://127.0.0.1:${port}/reports/inventory?format=csv`)
    const text = await res.text()
    assert.match(res.headers.get('content-type'), /text\/csv/)
    assert.ok(text.startsWith('id,title,author'), text.slice(0, 40))
    const j = await fetch(`http://127.0.0.1:${port}/health`)
    assert.deepEqual(await j.json(), { status: 'ok' })
  } finally {
    server.close()
  }
})
